"""The shared contract every part codes against. FROZEN for Phase 1: sessions do not edit this file (the main session
owns it; ask in your progress file if you need something here).

Parts (see PLAN.md): A graph core · B ingestion · C search · D learning · E evaluation · F product.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Literal, Protocol

# ---------------------------------------------------------------- graph schema (node labels and relationship types)
# Nodes. Every node has an integer `id` = pinned.graph.node_id(label, key) and stores its `key` string (upsert_nodes does
# both). <library> = the PyPI project name exactly as GitChameleon writes it (e.g. "scikit-learn"), lower-case.
# <dotted.path> = the import path a user writes, starting with the import name (e.g. "sklearn.linear_model.Ridge").
# Properties are scalars only (HydraDB has no list properties): lists are stored comma-joined.
LIBRARY = "Library"    # key: "<library>"                          props: name, import_names ("sklearn" or "a,b")
VERSION = "Version"    # key: "<library>|<version>"                props: library, version, ord (version_ord), released (YYYY-MM-DD)
API = "Api"            # key: "<library>|<dotted.path>"            props: library, path, kind (function|class|method|attr|module)
TERM = "Term"          # key: "<word>" (lower-case)                props: word
EPISODE = "Episode"    # key: "<run_id>|<problem_id>|<iteration>"  props: run_id, problem_id, library, version, passed, error_type, iteration

# Relationships (props in braces).
HAS_VERSION = "HAS_VERSION"   # Library -> Version
NEXT = "NEXT"                 # Version -> next Version of the same library
ADDED_IN = "ADDED_IN"         # Api -> Version           {evidence, sig}  sig = signature string at that version
REMOVED_IN = "REMOVED_IN"     # Api -> Version           {evidence}
CHANGED_IN = "CHANGED_IN"     # Api -> Version           {kind: signature|deprecated|behaviour, before, after, evidence}
REPLACED_BY = "REPLACED_BY"   # Api -> Api               {w, evidence, since_ord}
ALIAS_OF = "ALIAS_OF"         # Api -> Api (merge)       {evidence}
MEMBER_OF = "MEMBER_OF"       # Api -> Api (method -> class, class -> module)
CUES = "CUES"                 # Term -> Api              {w, source: doc|name|learned}
SHORTCUT = "SHORTCUT"         # Term -> Api              {w, lo_ord, hi_ord, hops}  applies when lo_ord <= ord(v) <= hi_ord
USED = "USED"                 # Episode -> Api           {helped: bool}

# Weights. Every CUES / SHORTCUT / REPLACED_BY edge ALWAYS carries `w` (HydraDB treats a missing property as false in
# WHERE, upstream #186). Ingestion writes W_DEFAULT; learning moves it; search ignores edges with w < W_FLOOR.
W_DEFAULT = 1.0
W_FLOOR = 0.2

# Validity rule (search implements it; everyone means the same thing by "valid"):
#   an Api is valid at version v  <=>  among its ADDED_IN / REMOVED_IN edges whose Version.ord <= ord(v), the one with
#   the highest ord is ADDED_IN (so remove-then-re-add works). No ADDED_IN at or before v -> "added_later" if a later
#   ADDED_IN exists, else "missing". CHANGED_IN with ord <= v and kind=deprecated -> "deprecated" (still usable).
# Signature at v: `after` of the latest CHANGED_IN{kind=signature} with ord <= v, else `sig` of the latest ADDED_IN <= v.
#
# Class names the parts export (the server and the eval harness import exactly these):
#   pinned.ingest.PyPIIngestor(graph, cache_dir=...)                      implements Ingestor
#   pinned.search.GraphSearch(graph)                                      implements Search
#   pinned.learn.GraphLearner(graph, ingestor=None, run_id="live", split_path=None)   implements Learner
#   pinned.learn.PlainStore (ablation arm: Search + Learner over a plain dict, no traversal)

Status = Literal["valid", "missing", "removed", "renamed", "changed", "added_later", "deprecated", "unknown"]


@dataclass
class Hop:
    """One step of an evidence chain, shown to the agent and in the UI."""

    src: str          # dotted path or "pandas 2.0"
    rel: str          # one of the relationship names above
    dst: str
    note: str = ""


@dataclass
class ContextItem:
    library: str
    path: str                     # the API the agent should use (or must avoid)
    status: Status
    chain: list[Hop] = field(default_factory=list)
    signature: str = ""           # signature AT the asked version, when known
    note: str = ""                # one plain line for the agent
    score: float = 0.0


@dataclass
class Context:
    library: str
    version: str
    items: list[ContextItem] = field(default_factory=list)
    query_ms: float = 0.0
    graph_queries: int = 0

    def to_prompt(self) -> str:
        """Plain text block given to the solver / agent. Owned by part C (may be improved there)."""
        lines = [f"Facts for {self.library}=={self.version} (from the Pinned graph):"]
        for it in self.items:
            chain = " ; ".join(f"{h.src} -{h.rel}-> {h.dst}" for h in it.chain)
            sig = f" signature: {it.signature}" if it.signature else ""
            lines.append(f"- {it.path}: {it.status}.{sig} {it.note} {('[' + chain + ']') if chain else ''}".rstrip())
        return "\n".join(lines)


@dataclass
class VersionFact:
    """One API at one version of the library's ladder (explain_api timeline)."""

    version: str
    ord: int
    status: Status
    signature: str = ""
    note: str = ""


@dataclass
class ApiTimeline:
    library: str
    path: str
    kind: str = ""
    versions: list[VersionFact] = field(default_factory=list)   # oldest -> newest, every ingested version
    replaced_by: list[Hop] = field(default_factory=list)        # REPLACED_BY / ALIAS_OF chain out of this API
    graph_queries: int = 0


@dataclass
class Finding:
    """One call in the agent's code, checked against the asked version (check_calls)."""

    call: str
    status: Status
    fix: str = ""
    chain: list[Hop] = field(default_factory=list)
    line: int | None = None


@dataclass
class Episode:
    """One attempt by a solver on one problem. The ONLY input to learning (train split only)."""

    run_id: str
    problem_id: str
    iteration: int
    library: str
    version: str
    problem: str
    starting_code: str
    context: Context | None
    code: str
    passed: bool
    error_type: str = ""          # e.g. AttributeError, TypeError, ImportError, AssertionError, Timeout
    error_text: str = ""          # trimmed traceback / message (never the hidden test source)


@dataclass
class LearnReport:
    edges_reweighted: int = 0
    shortcuts_added: int = 0
    gaps_ingested: int = 0
    merged: int = 0
    split: int = 0
    notes: list[str] = field(default_factory=list)


@dataclass
class IngestReport:
    library: str
    version: str
    apis: int = 0
    added: int = 0
    removed: int = 0
    changed: int = 0
    replaced: int = 0
    seconds: float = 0.0


# ---------------------------------------------------------------- interfaces (who implements what)
class Graph(Protocol):  # part A — pinned.graph.client.HydraGraph
    def query(self, cypher: str, params: dict | None = None) -> list[dict]: ...
    def write(self, cypher: str, params: dict | None = None) -> None: ...


class Ingestor(Protocol):  # part B — pinned.ingest
    def ingest_version(self, library: str, version: str) -> IngestReport: ...
    def fill_gap(self, library: str, version: str, hint: str) -> IngestReport: ...   # gap-driven ingestion (called by D)


class Search(Protocol):  # part C — pinned.search
    def context_for(self, problem: str, starting_code: str, library: str, version: str, k: int = 8) -> Context: ...
    def check_calls(self, code: str, library: str, version: str) -> list[Finding]: ...
    def explain_api(self, library: str, path: str) -> ApiTimeline: ...


class Learner(Protocol):  # part D — pinned.learn
    def record(self, episode: Episode) -> LearnReport: ...
    def maintain(self) -> LearnReport: ...   # path compression, merge/split, decay — once per iteration
